		INSERT INTO note_edges(space_id,source_note_id,target_note_id,relation,origin,created_by)
		VALUES($1,$2,$3,'supports','manual',$4)`, spaceID, notes[1], notes[0], userID); err != nil {
		t.Fatal(err)
	}

